CREATE OR REPLACE FUNCTION public.pm_branch_hours_write(p_token text, p_branch text, p_settings jsonb, p_page_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  clean_branch text := btrim(coalesce(p_branch, ''));
  merged jsonb;
begin
  perform pm_privacy.before_write(p_token);
  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id = s.login_id
  where s.token_hash = public.pm_token_hash(p_token)
    and s.expires_at > now() and a.active
  limit 1;

  if account.login_id is null or account.role not in ('main', 'general') then
    raise exception 'ADMIN_REQUIRED' using errcode = 'P0001';
  end if;
  if account.role = 'general'
     and jsonb_array_length(coalesce(account.branches, '[]'::jsonb)) > 0
     and not coalesce(account.branches ? clean_branch, false) then
    raise exception 'BRANCH_FORBIDDEN' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_settings) is distinct from 'object'
     or octet_length(p_settings::text) > 5000
     or length(coalesce(p_page_url, '')) > 500 then
    raise exception 'INVALID_BRANCH_HOURS' using errcode = 'P0001';
  end if;
  if not exists (
    select 1 from public.site_data sd
    cross join lateral jsonb_array_elements(case when jsonb_typeof(sd.payload) = 'array' then sd.payload else '[]'::jsonb end) branch
    where sd.data_key = 'pm-branches' and branch->>'name' = clean_branch
  ) then
    raise exception 'INVALID_BRANCH' using errcode = 'P0001';
  end if;

  insert into public.site_data(data_key, payload, page_url, updated_at)
  values ('pm-branch-hours', jsonb_build_object(clean_branch, p_settings), p_page_url, now())
  on conflict(data_key) do update
  set payload = (case when jsonb_typeof(public.site_data.payload) = 'object' then public.site_data.payload else '{}'::jsonb end)
                || jsonb_build_object(clean_branch, p_settings),
      page_url = excluded.page_url,
      updated_at = now()
  returning payload into merged;
  return merged;
end
$function$

CREATE OR REPLACE FUNCTION public.pm_sync_merge_by_id(p_token text, p_key text, p_payload jsonb, p_page_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  car_number text;
  current_payload jsonb;
  incoming_payload jsonb;
  remaining_payload jsonb;
  merged_payload jsonb;
  item jsonb;
  allowed_keys constant text[] := array[
    'pm-bookings', 'pm-service-runs', 'pm-messages',
    'pm-branch-transfer-requests', 'pm-work-audit'
  ];
begin
  perform pm_privacy.before_write(p_token);
  perform pm_privacy.customer_write(p_token,p_key,p_payload);
  perform pm_privacy.before_write(p_token);
  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id = s.login_id
  where s.token_hash = public.pm_token_hash(p_token)
    and s.expires_at > now()
    and a.active
  limit 1;

  if account.login_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'P0001';
  end if;
  if not (p_key = any(allowed_keys)) then
    raise exception 'KEY_NOT_ALLOWED' using errcode = 'P0001';
  end if;
  if jsonb_typeof(p_payload) <> 'array' then
    raise exception 'INVALID_PAYLOAD' using errcode = 'P0001';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_payload) value
    where btrim(coalesce(value->>'id', '')) = ''
  ) then
    raise exception 'ROW_ID_REQUIRED' using errcode = 'P0001';
  end if;

  car_number := coalesce(account.profile->>'car', '');
  if account.role not in ('main', 'general', 'developer') then
    if p_key not in ('pm-bookings', 'pm-service-runs', 'pm-messages', 'pm-work-audit') then
      raise exception 'KEY_NOT_ALLOWED' using errcode = 'P0001';
    end if;
    for item in select value from jsonb_array_elements(p_payload)
    loop
      if p_key = 'pm-work-audit' then
        if coalesce(item->>'car', '') <> car_number then
          raise exception 'FORBIDDEN_ROW' using errcode = 'P0001';
        end if;
      elsif not (
        item->>'memberId' = account.login_id
        or item#>>'{customer,id}' = account.login_id
      ) then
        raise exception 'FORBIDDEN_ROW' using errcode = 'P0001';
      end if;
    end loop;
  end if;

  select coalesce(jsonb_agg(d.item order by d.first_ordinality), '[]'::jsonb)
  into incoming_payload
  from (
    select distinct on (value->>'id') value as item, ordinality as first_ordinality
    from jsonb_array_elements(p_payload) with ordinality
    order by value->>'id', ordinality
  ) d;

  insert into public.site_data(data_key, payload, page_url, updated_at)
  values (p_key, '[]'::jsonb, p_page_url, now())
  on conflict (data_key) do nothing;

  select payload into current_payload
  from public.site_data
  where data_key = p_key
  for update;

  select coalesce(jsonb_agg(row.item order by row.ordinality), '[]'::jsonb)
  into remaining_payload
  from jsonb_array_elements(
    case when jsonb_typeof(current_payload) = 'array' then current_payload else '[]'::jsonb end
  ) with ordinality as row(item, ordinality)
  where not exists (
    select 1
    from jsonb_array_elements(incoming_payload) incoming
    where incoming->>'id' = row.item->>'id'
  );

  merged_payload := incoming_payload || remaining_payload;
  update public.site_data
  set payload = merged_payload,
      page_url = p_page_url,
      updated_at = now()
  where data_key = p_key;

  return jsonb_build_object('ok', true, 'count', jsonb_array_length(merged_payload));
end
$function$

CREATE OR REPLACE FUNCTION public.pm_sync_read(p_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  result jsonb := '[]'::jsonb;
  row_item record;
  scoped jsonb;
  public_keys constant text[] := array[
    'pm-branches','pm-notices','promotors-cases','pm-products','pm-blocked',
    'pm-blog-settings','pm-intro-slides','pm-home-view','pm-event-banners'
  ];
  private_keys constant text[] := array[
    'pm-customers','pm-bookings','pm-members','pm-service-runs','pm-messages',
    'pm-admin-notifications','pm-branch-transfer-requests','pm-work-audit',
    'pm-banned-members'
  ];
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('pm-privacy',0));
  result := jsonb_build_array(jsonb_build_object('data_key','pm-privacy-epoch','payload',jsonb_build_object('epoch',(select epoch from pm_privacy.config where singleton))));
  if coalesce(p_token, '') <> '' then
    select a.* into account
    from public.pm_sessions s
    join public.pm_accounts a on a.login_id = s.login_id
    where s.token_hash = public.pm_token_hash(p_token)
      and s.expires_at > now()
      and a.active
    limit 1;
  end if;

  for row_item in
    select data_key, payload from public.site_data where data_key = any(public_keys)
  loop
    result := result || jsonb_build_array(jsonb_build_object('data_key', row_item.data_key, 'payload', row_item.payload));
  end loop;

  if account.login_id is null then
    return result || jsonb_build_array(jsonb_build_object(
      'data_key','pm-auth-context','payload',jsonb_build_object('authenticated',false)
    ));
  end if;

  update public.pm_sessions
  set last_seen_at = now()
  where token_hash = public.pm_token_hash(p_token);

  result := result || jsonb_build_array(jsonb_build_object(
    'data_key','pm-auth-context',
    'payload',jsonb_build_object(
      'authenticated',true,'role',account.role,'branches',account.branches,'profile',account.profile
    )
  ));

  if account.role in ('main', 'general') then
    for row_item in
      select data_key,
        case
          when data_key = 'pm-members' and jsonb_typeof(payload) = 'array' then
            coalesce((select jsonb_agg(x - 'password') from jsonb_array_elements(payload) x), '[]'::jsonb)
          else payload
        end as payload
      from public.site_data
      where data_key = any(private_keys)
    loop
      result := result || jsonb_build_array(jsonb_build_object('data_key', row_item.data_key, 'payload', row_item.payload));
    end loop;
    return result;
  end if;


  result := result || jsonb_build_array(jsonb_build_object(
    'data_key','pm-members','payload',jsonb_build_array(account.profile)
  ));

  select coalesce(jsonb_agg(x), '[]'::jsonb) into scoped
  from public.site_data sd
  cross join lateral jsonb_array_elements(case when jsonb_typeof(sd.payload)='array' then sd.payload else '[]'::jsonb end) x
  where sd.data_key='pm-bookings'
    and ((x->>'memberId' = account.login_id or x#>>'{customer,id}' = account.login_id)
      and coalesce(nullif(x->>'memberId', ''), account.login_id) = account.login_id
      and coalesce(nullif(x#>>'{customer,id}', ''), account.login_id) = account.login_id);
  result := result || jsonb_build_array(jsonb_build_object('data_key','pm-bookings','payload',scoped));

  select coalesce(jsonb_agg(x), '[]'::jsonb) into scoped
  from public.site_data sd
  cross join lateral jsonb_array_elements(case when jsonb_typeof(sd.payload)='array' then sd.payload else '[]'::jsonb end) x
  where sd.data_key='pm-service-runs'
    and ((x->>'memberId' = account.login_id or x#>>'{customer,id}' = account.login_id)
      and coalesce(nullif(x->>'memberId', ''), account.login_id) = account.login_id
      and coalesce(nullif(x#>>'{customer,id}', ''), account.login_id) = account.login_id);
  result := result || jsonb_build_array(jsonb_build_object('data_key','pm-service-runs','payload',scoped));

  select coalesce(jsonb_agg(x), '[]'::jsonb) into scoped
  from public.site_data sd
  cross join lateral jsonb_array_elements(case when jsonb_typeof(sd.payload)='array' then sd.payload else '[]'::jsonb end) x
  where sd.data_key='pm-messages'
    and ((x->>'memberId' = account.login_id or x#>>'{customer,id}' = account.login_id)
      and coalesce(nullif(x->>'memberId', ''), account.login_id) = account.login_id
      and coalesce(nullif(x#>>'{customer,id}', ''), account.login_id) = account.login_id);
  result := result || jsonb_build_array(jsonb_build_object('data_key','pm-messages','payload',scoped));

  -- Vehicle-keyed legacy notes have no verified account owner. Keep them admin-only.
  result := result || jsonb_build_array(jsonb_build_object('data_key','pm-customers','payload','{}'::jsonb));

  return result;
end
$function$

CREATE OR REPLACE FUNCTION public.pm_sync_write(p_token text, p_key text, p_payload jsonb, p_page_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  car_number text;
  current_payload jsonb;
  merged jsonb;
  item jsonb;
  allowed_admin_keys constant text[] := array[
    'pm-branches','pm-notices','promotors-cases','pm-products','pm-blocked',
    'pm-customers','pm-bookings','pm-members','pm-blog-settings','pm-intro-slides',
    'pm-service-runs','pm-messages','pm-admin-notifications','pm-branch-transfer-requests',
    'pm-work-audit','pm-banned-members','pm-event-banners','pm-home-view'
  ];
begin
  perform pm_privacy.before_write(p_token);
  perform pm_privacy.customer_write(p_token,p_key,p_payload);
  perform pm_privacy.before_write(p_token);
  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id=s.login_id
  where s.token_hash=public.pm_token_hash(p_token)
    and s.expires_at>now() and a.active
  limit 1;

  if account.login_id is null then
    raise exception 'AUTH_REQUIRED' using errcode='P0001';
  end if;

  if account.role in ('main','general') then
    if not (p_key = any(allowed_admin_keys)) then
      raise exception 'KEY_NOT_ALLOWED' using errcode='P0001';
    end if;
    if p_key='pm-members' and jsonb_typeof(p_payload)='array' then
      select coalesce(jsonb_agg(x-'password'),'[]'::jsonb) into merged from jsonb_array_elements(p_payload) x;
    else
      merged := p_payload;
    end if;
    insert into public.site_data(data_key,payload,page_url,updated_at)
    values(p_key,merged,p_page_url,now())
    on conflict(data_key) do update
      set payload=excluded.payload,page_url=excluded.page_url,updated_at=now();
    if p_key='pm-banned-members' then
      update public.pm_accounts a
      set active = not exists (
        select 1 from jsonb_array_elements(case when jsonb_typeof(merged)='array' then merged else '[]'::jsonb end) b
        where b->>'type' in ('blocked','deleted')
          and (
            b#>>'{member,id}'=a.login_id
            or regexp_replace(coalesce(b#>>'{member,phone}',''),'[^0-9]','','g') =
               regexp_replace(coalesce(a.profile->>'phone',''),'[^0-9]','','g')
          )
      )
      where a.role='customer';
    end if;
    return jsonb_build_object('ok',true);
  end if;

  car_number := account.profile->>'car';

  if p_key in ('pm-bookings','pm-service-runs','pm-messages') then
    if jsonb_typeof(p_payload) <> 'array' then
      raise exception 'INVALID_PAYLOAD' using errcode='P0001';
    end if;
    for item in select value from jsonb_array_elements(p_payload)
    loop
      if not (
        item->>'memberId'=account.login_id
        or item#>>'{customer,id}'=account.login_id
      ) then
        raise exception 'FORBIDDEN_ROW' using errcode='P0001';
      end if;
    end loop;
    select payload into current_payload from public.site_data where data_key=p_key for update;
    select coalesce(jsonb_agg(x),'[]'::jsonb) into merged
    from jsonb_array_elements(case when jsonb_typeof(current_payload)='array' then current_payload else '[]'::jsonb end) x
    where not pm_privacy.exact_owner(x,account.login_id);
    merged := coalesce(merged,'[]'::jsonb) || p_payload;
    update public.site_data set payload=merged,page_url=p_page_url,updated_at=now() where data_key=p_key;
    return jsonb_build_object('ok',true);
  end if;

  if p_key='pm-customers' then
    if jsonb_typeof(p_payload)<>'object'
       or exists(select 1 from jsonb_object_keys(p_payload) k where k<>car_number) then
      raise exception 'FORBIDDEN_ROW' using errcode='P0001';
    end if;
    update public.site_data
    set payload=(case when jsonb_typeof(payload)='object' then payload else '{}'::jsonb end) || p_payload,
        page_url=p_page_url,updated_at=now()
    where data_key=p_key;
    return jsonb_build_object('ok',true);
  end if;

  if p_key='pm-members' then
    item := (case when jsonb_typeof(p_payload)='array' then p_payload->0 else p_payload end) - 'password';
    if item->>'id'<>account.login_id or item->>'car'<>car_number then
      raise exception 'FORBIDDEN_ROW' using errcode='P0001';
    end if;
    update public.pm_accounts set profile=item,updated_at=now() where login_id=account.login_id;
    select payload into current_payload from public.site_data where data_key=p_key for update;
    select coalesce(jsonb_agg(x),'[]'::jsonb) into merged
    from jsonb_array_elements(case when jsonb_typeof(current_payload)='array' then current_payload else '[]'::jsonb end) x
    where x->>'id'<>account.login_id;
    update public.site_data set payload=merged||jsonb_build_array(item),updated_at=now() where data_key=p_key;
    return jsonb_build_object('ok',true);
  end if;

  if p_key in ('pm-admin-notifications','pm-work-audit') and jsonb_typeof(p_payload)='array' then
    update public.site_data
    set payload=(case when jsonb_typeof(payload)='array' then payload else '[]'::jsonb end) || p_payload,
        page_url=p_page_url,updated_at=now()
    where data_key=p_key;
    return jsonb_build_object('ok',true);
  end if;

  raise exception 'KEY_NOT_ALLOWED' using errcode='P0001';
end
$function$

CREATE OR REPLACE FUNCTION public.pm_sync_delete_by_id(p_token text, p_key text, p_id text, p_page_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  current_payload jsonb;
  next_payload jsonb;
begin
  perform pm_privacy.before_write(p_token);
  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id = s.login_id
  where s.token_hash = public.pm_token_hash(p_token)
    and s.expires_at > now()
    and a.active
  limit 1;

  if account.login_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'P0001';
  end if;
  if account.role not in ('main', 'general', 'developer') then
    raise exception 'FORBIDDEN' using errcode = 'P0001';
  end if;
  if p_key <> 'pm-service-runs' or btrim(coalesce(p_id, '')) = '' then
    raise exception 'KEY_NOT_ALLOWED' using errcode = 'P0001';
  end if;

  select payload into current_payload
  from public.site_data
  where data_key = p_key
  for update;

  select coalesce(jsonb_agg(row.item order by row.ordinality), '[]'::jsonb)
  into next_payload
  from jsonb_array_elements(
    case when jsonb_typeof(current_payload) = 'array' then current_payload else '[]'::jsonb end
  ) with ordinality as row(item, ordinality)
  where row.item->>'id' <> p_id;

  update public.site_data
  set payload = next_payload,
      page_url = p_page_url,
      updated_at = now()
  where data_key = p_key;

  return jsonb_build_object('ok', true, 'count', jsonb_array_length(next_payload));
end
$function$
